const { mkdtempSync, writeFileSync, mkdirSync, rmSync } = await import("fs");
const { tmpdir } = await import("os");
const { join } = await import("path");
const { execFileSync } = await import("child_process");
const { pathToFileURL } = await import("url");
const repo = mkdtempSync(join(tmpdir(), "koala-risk-"));
try {
  execFileSync("git", ["init"], { cwd: repo, stdio: "pipe" });
  writeFileSync(join(repo, "AGENTS.md"), "local agents\n");
  writeFileSync(join(repo, "CLAUDE.md"), "local claude\n");
  mkdirSync(join(repo, "experiments", "reports"), { recursive: true });
  writeFileSync(join(repo, "experiments", "reports", "keep.json"), "{}\n");
  const mod = await import(pathToFileURL($root + "/packages/main/dist/core/baseline-risk.js").href);
  const risk = mod.collectBaselineRisk(repo, { acceptedLocalPaths: ["AGENTS.md", "CLAUDE.md"] });
  return { material: risk.materialEntries.map((e) => e.path), materialTotal: risk.materialTotal };
} finally { rmSync(repo, { recursive: true, force: true }); }

