const { writeFileSync, mkdirSync, rmSync } = await import("fs");
const { execFileSync } = await import("child_process");
const accepted = $root + "/.claude/skills/koala/fixture-accepted.md";
mkdirSync($root + "/.claude/skills/koala", { recursive: true });
writeFileSync(accepted, "accepted fixture\n");
try {
  const out = execFileSync(process.execPath, ["packages/main/dist/cli.js", "session_brief", "--concise"], { cwd: $root, encoding: "utf8" });
  return { hidesAccepted: !out.includes("fixture-accepted.md"), hasBrief: out.includes("# lattice session brief") };
} finally {
  rmSync(accepted, { force: true });
}

